          processSSELine(line, onChunk);
        }
        read();
      }).catch(err => {
        console.error('读取流出错:', err);
        if (err.name !== 'AbortError') {
          onError && onError(err);
        }
      });
    }
    read();
  }).catch(err => {
    console.error('Fetch 出错:', err);
    if (err.name !== 'AbortError') {
      onError && onError(err);
    }
  });
  return controller;
}

/**
 * 处理 SSE 格式的单行数据
 */
function processSSELine(line, onChunk) {
  // SSE 格式: "data:实际内容"
  if (line.startsWith('data:')) {
