 * @param {Object} data - { title } 会话标题
 */
export function createSession(data) {
  return request.post('/session/create', data)
}

/**
 * 删除会话
 * @param {string} sessionId - 会话 ID
 */
export function deleteSession(sessionId) {
  return request.delete(`/session/${sessionId}`)
}

/**
 * 获取会话消息列表
 * @param {string} sessionId - 会话 ID
 */
export function getMessages(sessionId) {
  return request.get(`/session/${sessionId}/messages`)
}

/**
 * 发送消息（普通模式）
 * @param {string} sessionId - 会话 ID
 * @param {Object} data - { content, model, temperature, maxTokens }
 */
export function sendMessage(sessionId, data) {
  return request.post(`/chat/${sessionId}`, data)
}

/**
 * 发送消息（流式模式）
 * @param {string} sessionId - 会话 ID
 * @param {Object} data - 发送的数据 { content }
 * @param {Function} onChunk - 接收到数据块的回调
 * @param {Function} onDone - 完成时的回调
 * @param {Function} onError - 错误时的回调
 * @returns {AbortController} - 用于取消请求
 */
export function sendMessageStream(sessionId, data, onChunk, onDone, onError) {
  const token = localStorage.getItem('token')
  const controller = new AbortController()

  fetch(`/api/chat/${sessionId}/stream`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token && { Authorization: `Bearer ${token}` })
    },
    body: JSON.stringify(data),
    signal: controller.signal
  })
    .then(response => {
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`)
      }
      console.log('开始读取 SSE 流')

      const reader = response.body.getReader()
      const decoder = new TextDecoder('utf-8')
      let buffer = ''

      function read() {
        reader.read().then(({ done, value }) => {
          if (done) {
            console.log('流读取完成')
            // 处理剩余 buffer
            if (buffer.trim()) {
              processSSELine(buffer, onChunk)
            }
            onDone && onDone()
            return
          }

          const text = decoder.decode(value, { stream: true })
          buffer += text

          // 按行分割处理 SSE 数据
          const lines = buffer.split('\n')
          // 保留最后一个不完整的行
          buffer = lines.pop() || ''

          for (const line of lines) {
            processSSELine(line, onChunk)
          }

          read()
        }).catch(err => {
          console.error('读取流出错:', err)
          if (err.name !== 'AbortError') {
            onError && onError(err)
          }
        })
      }
      read()
    })
    .catch(err => {
      console.error('Fetch 出错:', err)
      if (err.name !== 'AbortError') {
        onError && onError(err)
      }
    })

  return controller
}

/**
 * 处理 SSE 格式的单行数据
 */
function processSSELine(line, onChunk) {
  // SSE 格式: "data:实际内容"
  if (line.startsWith('data:')) {
    const content = line.substring(5)
    if (content && content !== '[DONE]') {
      console.log('收到 SSE 数据:', content.length, '字符')
      onChunk && onChunk({ content })
    }
  } else if (line.trim() && !line.startsWith(':')) {
    // 非标准 SSE 格式，直接作为内容处理
    console.log('收到原始数据:', line.length, '字符')
    onChunk && onChunk({ content: line })
  }
}
